import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Arbeitsbereich","description":"","frontmatter":{},"headers":[],"relativePath":"de/concepts/workspace.md","filePath":"de/concepts/workspace.md","lastUpdated":1784904021000}'),n={name:"de/concepts/workspace.md"};function r(p,e,h,d,l,o){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="arbeitsbereich" tabindex="-1">Arbeitsbereich <a class="header-anchor" href="#arbeitsbereich" aria-label="Permalink to &quot;Arbeitsbereich&quot;">​</a></h1><p>Der Arbeitsbereich ist das Verzeichnis, in dem swag2mcp alle seine Daten speichert — Konfiguration, zwischengespeicherte Spezifikationen, lokale Spezifikationsdateien, gespeicherte Antworten und Auth-Skripte.</p><h2 id="struktur" tabindex="-1">Struktur <a class="header-anchor" href="#struktur" aria-label="Permalink to &quot;Struktur&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # Arbeitsbereichs-Stammverzeichnis (Standard)</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # Konfigurationsdatei</span></span>
<span class="line"><span>├── cache/                            # Zwischengespeicherte entfernte Spezifikationsdateien</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # Zwischengespeicherter Spezifikationsinhalt</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # Cache-Metadaten (JSON)</span></span>
<span class="line"><span>├── specs/                            # Lokale Spezifikationsdateien</span></span>
<span class="line"><span>│   └── my-api.yaml</span></span>
<span class="line"><span>├── responses/                        # Gespeicherte API-Antworten (große Antworten)</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # Authentifizierungsskripte</span></span>
<span class="line"><span>    ├── meteo.sh                      # Unix-Shell-Skript</span></span>
<span class="line"><span>    └── meteo.bat                     # Windows-Batch-Skript</span></span></code></pre></div><h2 id="standardpfad" tabindex="-1">Standardpfad <a class="header-anchor" href="#standardpfad" aria-label="Permalink to &quot;Standardpfad&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong>: <code>~/.swag2mcp/</code></li><li><strong>Windows</strong>: <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="benutzerdefinierter-pfad" tabindex="-1">Benutzerdefinierter Pfad <a class="header-anchor" href="#benutzerdefinierter-pfad" aria-label="Permalink to &quot;Benutzerdefinierter Pfad&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/arbeitsbereich</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="verzeichnisse" tabindex="-1">Verzeichnisse <a class="header-anchor" href="#verzeichnisse" aria-label="Permalink to &quot;Verzeichnisse&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>Speichert heruntergeladene entfernte Spezifikationsdateien. Jede Datei wird mit einem SHA-256-Hash ihrer URL als Dateiname zwischengespeichert:</p><ul><li><code>{hash}.spec</code> — der zwischengespeicherte Spezifikationsdateiinhalt</li><li><code>{hash}.meta</code> — JSON-Metadaten (Quell-URL, Cache-Zeit, TTL)</li></ul><p>Jede zwischengespeicherte Datei hat eine zufällige TTL zwischen 1 Stunde und 48 Stunden. Der Cache wird bei jedem Start automatisch überprüft — wenn ein gültiger (nicht abgelaufener) Eintrag existiert, wird er ohne Download wiederverwendet.</p><p><strong>Befehle:</strong></p><ul><li><code>swag2mcp update</code> — leert den Cache und lädt alle Spezifikationen neu herunter</li><li><code>swag2mcp clean</code> — leert Cache und Antworten</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>Speichert lokale Spezifikationsdateien, auf die Collections über <code>location: specs/{name}</code> verweisen. Dateien hier werden direkt ohne Zwischenspeicherung verwendet.</p><p>Dieses Verzeichnis wird befüllt durch:</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;name&amp;gt;</code> — lädt eine entfernte Spezifikation herunter und speichert sie hier</li><li><code>swag2mcp export</code> — kopiert Spezifikationen von hier in das Export-ZIP</li><li>Manuelle Platzierung — Sie können Spezifikationsdateien selbst hierher kopieren</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p>Speichert API-Antworten, die das Limit <code>max_response_size</code> überschreiten (Standard 1 MB). Wenn der LLM einen Endpunkt aufruft und die Antwort zu groß ist, speichert swag2mcp sie hier und gibt stattdessen einen Dateiverweis zurück.</p><p>Namenskonvention: <code>{domain}-{method}-{path_with_underscores}-{6char_hex}.json</code></p><p>Alte Antworten werden automatisch nach 48 Stunden beim MCP-Server-Start bereinigt.</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p>Speichert Authentifizierungsskripte für den <code>script</code>-Auth-Typ. Jedes Skript ist nach der Domain der Spec benannt.</p><h4 id="namenskonvention" tabindex="-1">Namenskonvention <a class="header-anchor" href="#namenskonvention" aria-label="Permalink to &quot;Namenskonvention&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plattform</th><th>Dateiname</th><th>Beispiel</th></tr></thead><tbody><tr><td>Unix (Linux, macOS)</td><td><code>{domain}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domain}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>Die Domain darf keine <code>/</code>- oder <code>\\</code>-Zeichen enthalten.</p><h4 id="wie-skripte-funktionieren" tabindex="-1">Wie Skripte funktionieren <a class="header-anchor" href="#wie-skripte-funktionieren" aria-label="Permalink to &quot;Wie Skripte funktionieren&quot;">​</a></h4><ol><li>swag2mcp führt das Skript mit einem 30-Sekunden-Timeout aus</li><li>Das Skript muss gültiges JSON an die Standardausgabe ausgeben</li><li>swag2mcp parst das JSON und verwendet das Token für API-Anfragen</li></ol><h4 id="erwartetes-ausgabeformat" tabindex="-1">Erwartetes Ausgabeformat <a class="header-anchor" href="#erwartetes-ausgabeformat" aria-label="Permalink to &quot;Erwartetes Ausgabeformat&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ihr-token-hier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Feld</th><th>Typ</th><th>Erforderlich</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>Das Authentifizierungstoken</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td>Alternative zu <code>token</code> (zuerst geprüft)</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>Token-Typ (z. B. &quot;Bearer&quot;)</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>Token-Lebensdauer in Sekunden (Standard: 3600)</td></tr></tbody></table><h4 id="ausfuhrung" tabindex="-1">Ausführung <a class="header-anchor" href="#ausfuhrung" aria-label="Permalink to &quot;Ausführung&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Plattform</th><th>Befehl</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domain}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domain}.bat</code></td></tr></tbody></table><h4 id="token-zwischenspeicherung" tabindex="-1">Token-Zwischenspeicherung <a class="header-anchor" href="#token-zwischenspeicherung" aria-label="Permalink to &quot;Token-Zwischenspeicherung&quot;">​</a></h4><p>Das Token wird im Speicher zwischengespeichert, bis es abläuft. Bei jedem API-Aufruf überprüft swag2mcp zuerst den Cache — das Skript wird nur ausgeführt, wenn das zwischengespeicherte Token abgelaufen ist.</p><h4 id="stub-erstellung" tabindex="-1">Stub-Erstellung <a class="header-anchor" href="#stub-erstellung" aria-label="Permalink to &quot;Stub-Erstellung&quot;">​</a></h4><p>Wenn Sie <code>auth: { type: script, config: { domain: &quot;myapi&quot; } }</code> konfigurieren, erstellt swag2mcp automatisch ein Stub-Skript:</p><p><strong>Unix (<code>auth_scripts/myapi.sh</code>):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;ihr-token-hier&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows (<code>auth_scripts/myapi.bat</code>):</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ihr-token-hier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>Ersetzen Sie das Platzhalter-Token durch Ihre tatsächliche Authentifizierungslogik.</p><h4 id="bereinigung-verwaister-eintrage" tabindex="-1">Bereinigung verwaister Einträge <a class="header-anchor" href="#bereinigung-verwaister-eintrage" aria-label="Permalink to &quot;Bereinigung verwaister Einträge&quot;">​</a></h4><p>Wenn Sie eine Spec löschen, wird ihr Auth-Skript verwaist. swag2mcp entfernt verwaiste Skripte automatisch bei:</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="befehle" tabindex="-1">Befehle <a class="header-anchor" href="#befehle" aria-label="Permalink to &quot;Befehle&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Validiert die Konfiguration, leert Cache und Antworten und lädt dann alle Spezifikationsdateien neu herunter. Stellt auch sicher, dass Auth-Skripte existieren, und entfernt verwaiste Skripte.</p><p>Verwenden Sie diesen Befehl nach:</p><ul><li>Hinzufügen oder Entfernen von Collections</li><li>Ändern von Collection-Speicherorten</li><li>Bearbeiten von Spezifikationsdateien, die neu zwischengespeichert werden müssen</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Entfernt alle Inhalte von <code>cache/</code> und <code>responses/</code>, plus verwaiste Auth-Skripte. Spezifikationen werden NICHT neu zwischengespeichert — verwenden Sie dafür <code>update</code>.</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Validiert die Konfiguration einschließlich aller Collection-Speicherorte. Siehe <a href="./../cli/validate">CLI: validate</a>.</p><h2 id="export-und-import" tabindex="-1">Export und Import <a class="header-anchor" href="#export-und-import" aria-label="Permalink to &quot;Export und Import&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Arbeitsbereich in ZIP exportieren (Standardname: swag2mcp-backup-{date}.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In einen bestimmten Pfad exportieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/arbeitsbereich</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/sicherung.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Nur bestimmte Specs exportieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Aus Backup wiederherstellen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/sicherung.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/arbeitsbereich</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/zu/sicherung.zip</span></span></code></pre></div><p>Export enthält: <code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>. Cache und Antworten sind ausgeschlossen (es sind lokale Daten).</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>Wenn sich Ihr Arbeitsbereich in einem Git-Repository befindet, fügen Sie diese Einträge zu <code>.gitignore</code> hinzu:</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — nur lokale Daten</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p>Die Verzeichnisse <code>cache/</code> und <code>responses/</code> enthalten lokale, maschinenspezifische Daten, die nicht committet werden sollten. Alles andere (<code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>) sollte im Repository sein, damit die Konfiguration im Team geteilt wird.</p>`,66)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
